package com.ebuddy.service;
import com.ebuddy.domain.*; import com.ebuddy.repo.*; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.util.*;
@Component public class OutboxPublisher { private final OutboxRepository outbox; private final MessageRepository messages; private final SimpMessagingTemplate stomp; public OutboxPublisher(OutboxRepository o,MessageRepository m,SimpMessagingTemplate s){outbox=o;messages=m;stomp=s;} @Scheduled(fixedDelay=500) public void publish(){for(var item:outbox.findAll().stream().filter(x->x.getState()==OutboxState.pending).limit(100).toList()){try{var m=messages.findById(item.getMessageId());if(m.isPresent()){var x=m.get();var event=Map.of("v",1,"type",item.getEventType(),"event_id",x.getId().toString(),"cursor",String.valueOf(Optional.ofNullable(x.getSequence()).orElse(0L)),"data",Map.of("id",x.getId().toString(),"from_user_id",x.getSenderUserId().toString(),"to_user_id",x.getRecipientUserId().toString(),"body",x.getBody(),"status",x.getStatus().name()));var target=item.getEventType().startsWith("message.status")?x.getSenderUserId():x.getRecipientUserId();stomp.convertAndSendToUser(target.toString(),"queue/events",event);}item.done();outbox.save(item);}catch(RuntimeException e){item.retry();outbox.save(item);}}}}
